input.query:
SELECT DISTINCT split_part("RNA tissue specific nTPM", ':', 1) AS tissue_name 
FROM proteinatlas 
WHERE "RNA tissue specificity" = 'Tissue enriched';

SELECT sum(cnt) FROM (
    SELECT split_part("RNA tissue specific nTPM", ':', 1) AS tissue, count(*) as cnt
    FROM proteinatlas 
    WHERE "RNA tissue specificity" = 'Tissue enriched'
    GROUP BY tissue
);
